theorem lg_target (n : ℕ) : Real.log ↑(n + 1) ≤ ↑(harmonic n) := by
  intro n
  cases n
  case zero {
    simp [harmonic, Real.log_add]
  }
  case succ n' {
    have h : Real.eulerMascheroniConstant ≈ 0.5772 := by decide_numeral
    have h1 : 1 / n' + Real.eulerMascheroniConstant < 1 := by linarith
    have h2 : Real.log ↑(n + 1) ≤ ↑(harmonic n) :=
      by {
        apply Real.tendsto_harmonic_sub_log.mp Filter.atTop (nhds Real.eulerMascheroniConstant) n
        exact Real.log_div_le_sum_range_add 0 1 n
      }
    exact h2
  }
